INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(40216, 0, 0, 0, 0, 0, 0, 0, 0, 'Revenge, such a sweet thing, perhaps now, people will know not to step all over Shizwackle!$B$BI\'ve learned a valueable lesson thanks to you pal, not to just trust every old sap with a bundle of gold offering riches.$B$BTake this coin for the trouble, I actually pay people for work!', 0),
(40388, 0, 0, 0, 0, 0, 0, 0, 0, 'My suspicions confirmed, they are far more cunning than I gave them credit for. This does not seem to be over, $N. Thank you for getting this information to me. I\'ll send a runner to Orgrimmar and Far Watch Post right away to make sure they hear of this Death\'s Head.', 0),
(40389, 0, 0, 0, 0, 0, 0, 0, 0, 'The head of Zalazane? No, it could never be that easy.$B$B<As you and the great chieftain observe the witchdoctor\'s head, it slowly loses its form and resembles that of another troll, perhaps a mindslave>.$B$BIt will not be so easy to reclaim the Echo Isles from Zalazane and his army of slaves, but at least we have contained the threat for now.$B$BThere are those who will not understand my decision to keep Thrall from reclaiming the isles for my tribe, but we are indebted once to the Warchief and his people and now we will prove that their faith was not misplaced. When the time comes, $N, I hope to see you on the battlefield beside my tribe.', 0),
(40390, 0, 0, 0, 0, 0, 0, 0, 0, 'The Kolkar have proven a long-standing threat to our people since settling on these shores, but it appears they will trouble us no further. Your victory over the centaur today is just one step closer to securing Durotar from local threats.', 0),
(40391, 0, 0, 0, 0, 0, 0, 0, 0, 'The wretched Kolkar dwindle in their presence throughout Kalimdor under the watchful presence of the Horde. We are blessed for our alliance and may begin focusing on larger threats lurking just out of sight.$B$BThe very land we depend on cries out for help, $N, and we must figure out how best to answer her plea quickly. Your victory brings me joy and solace to the many tauren that suffered under Kolkanis\' cruel raids before the Horde\'s arrival.$B$BGo with the Earthmother\'s blessing on your journey.', 0),
(40419, 0, 0, 0, 0, 0, 0, 0, 0, 'We have our hands full of work. I wasn\'t able to spare any of my men to send the report back to Stonard.$B$BBut since you are here now, you might be able to help us with the matters at hand.', 0),
(40420, 0, 0, 0, 0, 0, 0, 0, 0, 'A mine of extraordinary size, you say?$B$BGood, I will write about it in the report. We still have other issues to worry about before I send this off, speak with Jaiymu and Bagaroh for more tasks.', 0),
(40421, 0, 0, 0, 0, 0, 0, 0, 0, 'Good job, $C. I wish I could\'ve seen them dying.', 0),
(40422, 0, 0, 0, 0, 0, 0, 0, 0, 'Hah, good job again.$B$BThank you, friend. Thank you for all you do for the Horde.', 0),
(40423, 0, 0, 0, 0, 0, 0, 0, 0, 'Twenty heads. I rarely smile, but you earned it.$B$B<Bagaroh grins>$B$BTime to get back to work.', 0),
(40424, 0, 0, 0, 0, 0, 0, 0, 0, '<Ruag glances over the report>.$B$BGreat work, soldier. I am relieved to hear that the expedition is safe. I am also impressed. You did a lot of work, good work. Please, pick some equipment from our armory. Whatever you like.$B$BStay safe, soldier.', 0),
(40513, 0, 0, 0, 0, 0, 0, 0, 0, 'Hurry, smash the ring, it contains the magic that has kept me enslaved!', 0),
(40665, 0, 0, 0, 0, 0, 0, 0, 0, 'You have done well, but do not yet sing for victory: Our foe is as vicious as it is relentless.', 0),
(40666, 0, 0, 0, 0, 0, 0, 0, 0, 'Proudmoore thought us ill-made mongrels, unthinking and mad with bloodlust.$B$BBut true warfare requires strategic acuity as much as it requires a sharp edge and strong guts.$B$BYou have done well, $N. We have defeated the Kul Tirans once, we shall defeat them again.', 0),
(40667, 0, 0, 0, 0, 0, 0, 0, 0, 'I see you carry Dar\'nakk\'s commendation. I\'ve never known him to grant such accolades freely.$B$BYou did well in defending our coasts, and for that the Horde owes you its gratitude.', 0),
(40668, 0, 0, 0, 0, 0, 0, 0, 0, 'So, he sent you?$B$BI see.', 0),
(40669, 0, 0, 0, 0, 0, 0, 0, 0, '<Mally O\'Flor would take careful time analyzing the blood.>$B$BYou honor your word, and so I shall honor mine.', 0),
(40670, 0, 0, 0, 0, 0, 0, 0, 0, 'It is always useful to have information, it helps one not step on their own feet.$B$BDo not forget that $N.$B$BYou\'ve done well, and now we can act without worry.', 0),
(40671, 0, 0, 0, 0, 0, 0, 0, 0, 'I advised the Warchief against the sending of envoys. It was no use with a man like Alverold.$B$BOur men were cowardly assailed under the flag of peace. Those treacherous Kul Tirans tied them to stakes, soaked them in tar and burned them alive on the shore.$B$BNow we hold nothing back, now we put an end to them!', 0),
(41135, 0, 0, 0, 0, 0, 0, 0, 0, 'You don\'t have to join any orcish coven mon, but you should use them to your advantage. This orc here, this Nartok, he be talking too much. He doesn\'t really know how to twist the demons to his advantage, he is just speaking big words like he be some chosen one. Never think that mon, by summoning the demons from the Twisting Nether, you\'ve chosen to live your life away from the Loa. And one day that will catch up to you.$B$BAnyway, if you bring me an offering, me be glad to teach you. Perhaps one day you will be as strong as the Zandalari Demoniacs!', 0),
(50305, 0, 0, 0, 0, 0, 0, 0, 0, 'Good.$B$BLet me tell you one thing before you waste it in a feeble attempt of cooking it. It\'s about the amount of spices that your meat gets ready, not about the amount of fire.$B$BWell, fire is needed anyway…', 0),
(60131, 0, 0, 0, 0, 0, 0, 0, 0, 'It\'s important to keep their numbers in check but not to hunt them to the brink. You\'ve done a great service for the Horde this day, $C. Go with honor.', 0),
(60133, 0, 0, 0, 0, 0, 0, 0, 0, 'Thank you, $N. The sacrifice of these poor animals will help me to unravel this mysterious taint seeping into the grassland and develop a cure for its effects.', 0),
(60134, 0, 0, 0, 0, 0, 0, 0, 0, 'I saw a small herd of gazelle pass by the Crossroads while you were gone. They traveled like the wind itself carried their hooves higher, and it gave me much joy to see them run freely. Thank you, $N, for your help.', 0),
(60139, 0, 0, 0, 0, 0, 0, 0, 0, 'For the first time in weeks I think I can close my eyes and not hear their chittering. It\'s done.$B$B<Blackarm laughs aloud, exasperated>.$B$BYou will be counted among the great heroes of the Horde for this effort, $C, if I have anything to say about it. Have some of these healing potions for your trouble. With any luck, I won\'t need so many anymore.', 0),
(60147, 0, 0, 0, 0, 0, 0, 0, 0, 'You have struck a blow to their numbers, and returned in one piece.$B$BTake one, you earned it.', 0),
(70052, 0, 0, 0, 0, 0, 0, 0, 0, 'You\'re back, great.$B$BAnd I see you picked something up as a trophy. Strange, but whatever floats your boat, bub!$B$BHere\'s some coin for your troubles.', 0),
(80384, 0, 0, 0, 0, 0, 0, 0, 0, 'Ahahahhah! Good job, mon! For my part of the deal...$B$B<Lau\'Tiki crack opens one of the shells and extracts something from it.>$B$BHere\'s da secret, mon. This tiny pesky bastard might come in handy when ya tame it and feed it. Though never fully trust it, dey like nibbling on fingers.', 0),
(80395, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh you\'re an adventurer that has come to investigate the lights aren\'t you? Don\'t worry, I was merely experimenting with a special matter transmitter and it is of no danger to anyone!$B$BFear not, my experiment will be of use to everyone once it succeeds! On the other hand, I have a task for you if you wish to keep this area safer!', 0),
(80399, 0, 0, 0, 0, 0, 0, 0, 0, 'Zalazane\'s mojo and his apprentice\'s head? A job well-done. Here, I\'ve got a reward for you. Just pick which one you want.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(40216, 0, 0, 'They deserve every licking they get, don\'t up and go soft on me!', 0),
(40388, 0, 0, 'You look troubled, $N. Tell me what bothers you.', 0),
(40389, 0, 0, 'I do not have long to speak, $C. What is it you bring to me?', 0),
(40390, 0, 0, 'What do you have there, $C?', 0),
(40391, 0, 0, 'You carry the presence of a victorious hunt, $C? Come closer, show me what you carry.', 0),
(40419, 0, 0, 'Ruag sent you? I didn\'t expect him to hire a search party that soon.', 0),
(40420, 0, 0, 'Any success?', 0),
(40421, 0, 0, 'How many have you killed?', 0),
(40422, 0, 0, 'Have you found the Altar of Storms?', 0),
(40423, 0, 0, 'Got the heads?', 0),
(40424, 0, 0, 'It\'s you! What happened to the expedition?', 0),
(40513, 0, 0, 'Hurry, I cannot stand another second of this! Baaaa!', 0),
(40665, 0, 0, 'Throw them back into the waves. Let the sea churn red with their blood.', 0),
(40666, 0, 0, 'Have you taken their provisions, $C?', 0),
(40667, 0, 0, 'Lok-regar no\'gal, $R. I bid you welcome.', 0),
(40668, 0, 0, 'What can I do for you?', 0),
(40669, 0, 0, 'Have you had any progress?', 0),
(40670, 0, 0, 'Have you had any progress?', 0),
(40671, 0, 0, 'You return, and not a moment too soon.', 0),
(41135, 0, 0, 'Hey mon. I be Zin\'jashi, and I welcome you.$B$BI be of the Revantusk Tribe, and I be here to teach young trolls the ways of the Twisting Nether. The demons are powerful subjects mon, but they be very treacherous - so be very careful!', 0),
(50305, 0, 0, 'You got the meat?', 0),
(60131, 0, 6, 'You smell of the sea, $C. Tell me the beast is slain so I can get the fisherman back to work.', 0),
(60133, 66, 6, 'It is with a heavy heart that I must send you to do this deed, $N.$B$BDo not delay, the herds only grow weaker.', 0),
(60134, 66, 6, 'Is it done? We can prevent harm to all of the Earthmother\'s creatures if only the grazers are protected against this poison.', 0),
(60139, 0, 0, 'Is it done? Have you scoured the land for the stinging menace?', 0),
(60147, 0, 0, 'What are you waiting for?', 0),
(70052, 0, 0, 'In life we make choices we sometimes regret, and Tazan will be sure to regret this one.', 0),
(80384, 0, 0, 'Hunt them, bring me their shells!', 0),
(80395, 0, 0, 'Oh my, greetings! Who are you?', 0),
(80399, 0, 0, 'What do you have there, $N?', 0);
