INSERT INTO `page_text` (`ID`, `Text`, `NextPageID`, `VerifiedBuild`) VALUES
(50678, 'Me bothers not writing too much here mon. Zol\'majin sends I from Revantusk Village to be teaching the youngins about the Fel magic. If you not be dead as you be reading this, it means you have the talent to summon the will of the Twisting Nether at your own fingertips.$B$BBut be careful mon, felfire burns worse than normal fire! Me be resting in this cave they be calling a Den — next to some other warlock that seems to have a weird syndrome, he believes himself to be some chosen one. Me be hoping you not be as boring as he.$B$B<The rest of the page is covered with a drawing that symbolizes a big-headed orc.', 0, 0);
