INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(61026, 50, 0, 'The enemy draws near brothers and sisters of the Horde! Answer the call for war, and fight off the enemies that dare challenge us!', 12, 0, 100, 0, 0, 0, 0, 0, 'Warbringer Dar\'nakk - Turtle C++'),
(60846, 0, 0, 'I AM FREE! AT LONG LAST FREE FROM THAT CURSED FORM!', 12, 0, 100, 15, 0, 0, 0, 0, 'Lashog - Turtle C++'),
(60846, 1, 0, 'Take that ring, I cannot stand to look at it, thank you for everything, I will leave when I have collected myself.', 12, 0, 100, 1, 0, 0, 0, 0, 'Lashog - Turtle C++'),
(61052, 0, 0, 'A few weeks ago Kul Tiras was allowed embassy within the city of Stormwind, given by Bolvar Fordragon in an attempt to improve diplomacy between the two nations.', 12, 0, 100, 1, 0, 0, 0, 0, 'Mally O\'Flor - Turtle C++'),
(61052, 1, 0, 'While things seem to be going fairly well, it is quite obvious to many that Kul Tiras is still very stubborn on their ideals and traditions, their sanctity of honor, and respect for the fallen is on par with many of the most noble paladin.', 12, 0, 100, 1, 0, 0, 0, 0, 'Mally O\'Flor - Turtle C++'),
(61052, 2, 0, 'As of current, there has been no consensus, Stormwind is not looking to be dragged into a war without good reason, I am under good authority and good information to inform of no cooperation between Kul Tiras, and the Alliance in this matter. This \'invasion\' you are facing is, by our eyes, up to Thrall to handle, and deal with as he seeks fit.', 12, 0, 100, 1, 0, 0, 0, 0, 'Mally O\'Flor - Turtle C++'),
(61052, 3, 0, 'The SI:7 has given me clear authority to pass along this information for the better interest of both parties. Bring this to your leader, and let him know.', 12, 0, 100, 1, 0, 0, 0, 0, 'Mally O\'Flor - Turtle C++');
